// Minduck's desktop chrome. Figure artwork and upstream conversation UI stay separate.
import { clamp } from './ui.js';
import { createQaView, createQuickChatView, createRunningView } from './minduck-qa/view.js';
import qaStyles from './minduck-qa/styles.js';

const icon = (path) => `<svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
  <path d="${path}" stroke="currentColor" stroke-width="1.2"
    stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const NEW_CHAT = icon(`
  M8.24098 3.31819
  H5.23521
  C4.03279 3.31819 3.43158 3.31819 2.97232 3.5522
  C2.56834 3.75804 2.23989 4.08648 2.03406 4.49046
  C1.80005 4.94972 1.80005 5.55093 1.80005 6.75335
  V12.7649
  C1.80005 13.9673 1.80005 14.5685 2.03406 15.0278
  C2.23989 15.4318 2.56834 15.7602 2.97232 15.966
  C3.43158 16.2 4.03279 16.2 5.23521 16.2
  H11.2467
  C12.4492 16.2 13.0504 16.2 13.5096 15.966
  C13.9136 15.7602 14.2421 15.4318 14.4479 15.0278
  C14.6819 14.5685 14.6819 13.9673 14.6819 12.7649
  V9.75912
  M6.09398 11.9061
  H7.29238
  C7.64247 11.9061 7.81751 11.9061 7.98224 11.8665
  C8.12829 11.8315 8.2679 11.7737 8.39597 11.6952
  C8.54041 11.6067 8.66419 11.4829 8.91173 11.2353
  L15.7554 4.39168
  C16.3483 3.79881 16.3483 2.83757 15.7554 2.2447
  C15.1625 1.65183 14.2013 1.65183 13.6084 2.2447
  L6.76474 9.08836
  C6.51719 9.33591 6.39342 9.45969 6.3049 9.60413
  C6.22642 9.73219 6.16859 9.87181 6.13353 10.0179
  C6.09398 10.1826 6.09398 10.3576 6.09398 10.7077
  V11.9061
  Z
`);
const TOGGLE_TASKS = icon('M13.5 11.25L9 6.75L4.5 11.25');

export function createMinduckPanels({ onAction, onFocus, onReleaseFocus } = {}) {
  const stack = document.createElement('div');
  stack.className = 'minduck-outputs';
  stack.setAttribute('role', 'region');
  stack.setAttribute('aria-label', 'Matter 活动会话');
  stack.hidden = true;
  const outputs = new Map();
  const views = new Map(), runningViews = new Map(), dismissed = new Set();
  let latestTasks = [], queueKeys = [], expanded = false, displayExpanded = false;
  let motions = [], motionId = 0, lastLayout = null, motionBounds = '';
  const layers = [1, 2].map(depth => {
    const layer = document.createElement('div');
    layer.className = 'minduck-panel minduck-stack-layer';
    layer.style.setProperty('--stack-depth', depth);
    layer.setAttribute('aria-hidden', 'true');
    layer.hidden = true;
    stack.appendChild(layer);
    return layer;
  });
  const list = document.createElement('div');
  list.id = 'minduck-task-list';
  list.className = 'minduck-output-list';
  list.setAttribute('aria-label', '活动会话列表');
  stack.appendChild(list);
  list.addEventListener('click', event => {
    if (expanded || queueKeys.length < 2 || event.target.closest('.minduck-close')) return;
    event.preventDefault();
    event.stopPropagation();
    setExpanded(true);
  }, true);
  const messageKey = task => [task.conversationId || 'current', task.turnId || '',
    task.qa ? task.qa.contextId + ':' + task.qa.itemId : task.status || 'active'].join(':');
  function card(id) {
    if (outputs.has(id)) return outputs.get(id);
    const output = document.createElement('section');
    output.className = 'minduck-panel minduck-output';
    output.dataset.conversationId = id;
    output.setAttribute('role', 'group');
    output.innerHTML = '<div class="minduck-content"><button type="button" class="minduck-message"><span class="minduck-output-line"></span><span class="minduck-output-line secondary"></span></button><div class="minduck-running" hidden></div><div class="minduck-qa" hidden></div></div><button type="button" class="minduck-close" aria-label="关闭这条桌宠消息" title="关闭这条消息">×</button>';
    const message = output.querySelector('.minduck-message');
    message.addEventListener('click', async () => {
      try { await onAction?.('open-conversation', { conversationId: output.dataset.conversationId,
        turnId: output.dataset.turnId || '' }); }
      catch (error) { console.error('无法打开 Matter 会话:', error); }
    });
    output.querySelector('.minduck-close').addEventListener('click', event => {
      event.stopPropagation();
      dismissed.add(output.dataset.messageKey);
      if (dismissed.size > 200) dismissed.delete(dismissed.values().next().value);
      onReleaseFocus?.();
      setOutputs(latestTasks);
    });
    outputs.set(id, output);
    list.appendChild(output);
    return output;
  }

  const actions = document.createElement('div');
  actions.className = 'minduck-panel minduck-actions';
  actions.setAttribute('role', 'group');
  actions.setAttribute('aria-label', 'Matter 快捷操作');
  actions.hidden = true;
  let composing = false, composerBusy = false, quickView;
  function closeComposer() {
    composing = false;
    actions.classList.remove('is-composing');
    quickView.update(false);
    onReleaseFocus?.();
  }
  function openComposer() {
    composing = true;
    actions.classList.add('is-composing');
    quickView.update(true);
    onFocus?.();
  }
  const chatButton = document.createElement('button');
  chatButton.type = 'button';
  chatButton.className = 'minduck-action';
  chatButton.dataset.action = 'new-chat';
  chatButton.setAttribute('aria-label', '和 Matter 聊天');
  chatButton.disabled = typeof onAction !== 'function';
  chatButton.setAttribute('aria-disabled', String(chatButton.disabled));
  chatButton.title = '和 Matter 聊天';
  chatButton.innerHTML = NEW_CHAT;
  chatButton.addEventListener('click', openComposer);
  actions.appendChild(chatButton);
  const quick = document.createElement('div');
  quick.className = 'minduck-quick';
  quick.setAttribute('aria-label', '和 Matter 聊天');
  actions.appendChild(quick);
  let notificationCount = 0;
  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = 'minduck-action';
  toggle.dataset.action = 'toggle-tasks';
  toggle.setAttribute('aria-controls', list.id);
  toggle.innerHTML = TOGGLE_TASKS;
  toggle.addEventListener('click', () => setExpanded(!expanded));
  actions.insertBefore(toggle, quick);
  function syncPresentation() {
    const depth = displayExpanded ? 0 : Math.min(2, Math.max(0, queueKeys.length - 1));
    stack.classList.toggle('is-expanded', displayExpanded);
    stack.style.setProperty('--stack-offset', `${depth * 6}px`);
    layers.forEach((layer, index) => { layer.hidden = index >= depth; });
    for (const [id, output] of outputs) output.hidden = stack.hidden || (!displayExpanded && id !== queueKeys[0]);
    list.tabIndex = expanded ? 0 : -1;
    const label = (expanded ? '折叠任务会话' : '展开任务会话')
      + (notificationCount ? `，${notificationCount} 个会话通知` : '');
    toggle.setAttribute('aria-expanded', String(expanded));
    toggle.setAttribute('aria-label', label);
    toggle.title = label;
    toggle.disabled = !queueKeys.length;
    toggle.setAttribute('aria-disabled', String(toggle.disabled));
    if (!displayExpanded || stack.hidden) stack.classList.remove('has-scroll-above', 'has-scroll-below');
  }
  function updateScrollEdges() {
    const visible = !stack.hidden && displayExpanded && !motions.length;
    stack.classList.toggle('has-scroll-above', visible && list.scrollTop > 1);
    stack.classList.toggle('has-scroll-below', visible && list.scrollTop + list.clientHeight < list.scrollHeight - 1);
  }
  list.addEventListener('scroll', updateScrollEdges, {passive:true});
  function measureCards() {
    const viewport = list.getBoundingClientRect();
    return {
      viewport,
      folded: !displayExpanded,
      moving: motions.length > 0,
      backs: layers.filter(layer => !layer.hidden).map(layer => layer.getBoundingClientRect()),
      cards: new Map([...outputs].filter(([, card]) => !card.hidden).map(([id, card]) => {
        const rect = card.getBoundingClientRect(), style = getComputedStyle(card);
        return [id, { rect, clip: style.clipPath, opacity: Number(style.opacity),
          contentOpacity: Number(getComputedStyle(card.firstElementChild).opacity),
          // Boundary contact can differ by a few native subpixels after scaling.
          visible: style.visibility !== 'hidden' && rect.bottom > viewport.top + .02 * scale
            && rect.top < viewport.bottom - .02 * scale }];
      })),
    };
  }
  function stopMotion() {
    motionId++;
    for (const animation of motions) animation.cancel();
    motions = [];
    for (const card of outputs.values()) {
      card.style.removeProperty('z-index'); card.style.removeProperty('visibility');
    }
    stack.classList.remove('is-transitioning');
    stack.style.removeProperty('clip-path');
  }
  const relayout = () => { if (lastLayout) layout(...lastLayout); };
  function settleMotion() {
    stopMotion(); displayExpanded = expanded; syncPresentation(); relayout();
  }
  function deckFrame(base, target, front) {
    const top = Math.max(0, (base.height - target.height) / scale);
    const side = Math.max(0, (base.width - target.width) / scale / 2);
    return { translate: `${(target.left + target.width / 2 - base.left - base.width / 2) / scale}px ${(target.bottom - base.bottom) / scale}px`,
      ...(front ? {} : { clipPath: `inset(${top}px ${side}px 0px round 19px)` }), opacity: 1 };
  }
  function deckTiming(before, folded, spread, next) {
    const id = queueKeys[0], closed = folded.cards.get(id).rect, opened = spread.cards.get(id).rect;
    const distance = Math.hypot(opened.left - closed.left, opened.top - closed.top);
    const start = before.cards.get(id)?.rect || closed, end = next ? opened : closed;
    const remaining = Math.min(1, Math.hypot(end.left - start.left, end.top - start.top) / Math.max(1, distance));
    const pixels = distance / scale;
    const fullDuration = next ? clamp(180 + pixels * .4, 180, 260) : clamp(130 + pixels * .3, 140, 200);
    return {
      duration:Math.round(before.moving ? clamp(fullDuration * Math.sqrt(remaining), 100, fullDuration) : fullDuration),
      stagger:before.moving ? 0 : next ? 16 : 8,
      easing:next ? 'cubic-bezier(.22,.8,.22,1)' : 'cubic-bezier(.32,0,.2,1)',
    };
  }
  function setExpanded(value) {
    const next = Boolean(value && queueKeys.length);
    if (next === expanded && !motions.length) return;
    const before = measureCards();
    stopMotion(); expanded = next;
    if (!next && list.contains(document.activeElement)) toggle.focus({ preventScroll:true });
    list.scrollTop = 0;
    if (!lastLayout || stack.hidden || matchMedia('(prefers-reduced-motion:reduce)').matches) {
      displayExpanded = next; syncPresentation(); relayout(); return;
    }
    // Measure both resting layouts without painting an intermediate state.
    displayExpanded = false; syncPresentation(); relayout();
    const folded = measureCards();
    displayExpanded = true; syncPresentation(); relayout();
    const spread = measureCards(), token = ++motionId;
    const timing = deckTiming(before, folded, spread, next);
    stack.classList.add('is-transitioning');
    // Include both placements while moving, but never reveal off-viewport queued rows.
    const bounds = stack.getBoundingClientRect();
    const top = Math.min(folded.viewport.top, spread.viewport.top) - 8 * scale;
    const bottom = Math.max(folded.viewport.bottom, spread.viewport.bottom) + 8 * scale;
    stack.style.clipPath = `inset(${(top - bounds.top) / scale}px -8px ${(bounds.bottom - bottom) / scale}px -8px)`;
    motionBounds = `${innerWidth}:${innerHeight}:${scale}`;
    queueKeys.forEach((id, index) => {
      const card = outputs.get(id), base = spread.cards.get(id), previous = before.cards.get(id);
      if (!base || (index > 2 && !previous?.visible)) {
        card.style.visibility = 'hidden'; return;
      }
      const front = index === 0;
      const target = front ? folded.cards.get(queueKeys[0]).rect
        : folded.backs[Math.min(index - 1, folded.backs.length - 1)];
      const deck = deckFrame(base.rect, target || folded.cards.get(queueKeys[0]).rect, front);
      const resting = { translate:'0px 0px', opacity:1,
        ...(front ? {} : { clipPath:'inset(0px 0px 0px round 28px)' }) };
      const from = before.folded ? deck : previous ? {
        translate:`${(previous.rect.left - base.rect.left) / scale}px ${(previous.rect.top - base.rect.top) / scale}px`,
        opacity:previous.opacity, ...(front ? {} : {clipPath:previous.clip === 'none' ? resting.clipPath : previous.clip}),
      } : { ...deck, opacity:0 };
      if (!before.folded && !before.moving && previous && !previous.visible && front) Object.assign(from, deck, {opacity:0});
      const to = next ? resting : {...deck, opacity:index > 2 ? 0 : 1};
      const delay = Math.min(index, 2) * timing.stagger;
      const reveal = next && !before.moving ? Math.min(70, timing.duration * .28) : 0;
      card.style.zIndex = String(queueKeys.length - index);
      motions.push(card.animate([from, to], {duration:timing.duration, delay,
        easing:timing.easing, fill:'both'}));
      if (!front) motions.push(card.firstElementChild.animate([
        {opacity:before.folded ? 0 : previous?.contentOpacity ?? 0}, {opacity:next ? 1 : 0},
      ], {duration:next ? Math.min(140, timing.duration - reveal) : Math.min(85, timing.duration * .55),
        delay:delay + reveal, easing:'ease-out', fill:'both'}));
    });
    Promise.all(motions.map(animation => animation.finished)).then(() => {
      if (token === motionId) settleMotion();
    }).catch(() => {});
  }
  function nestedCanScrollUp(event) {
    for (const element of event.composedPath()) {
      if (element === list || element === stack) break;
      if (element instanceof Element && element.scrollTop > 1
        && /^(auto|scroll|overlay)$/.test(getComputedStyle(element).overflowY)) return true;
    }
    return false;
  }
  stack.addEventListener('wheel', event => {
    if (event.defaultPrevented || event.ctrlKey || event.metaKey || event.shiftKey
      || !event.deltaY || Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
    const down = event.deltaY > 0;
    const unfold = down && !expanded && queueKeys.length > 1;
    const fold = !down && expanded && list.scrollTop <= 1 && !nestedCanScrollUp(event);
    // Keep wheel continuation from jumping past the deck transition.
    if (unfold || fold || (motions.length && down === expanded)) {
      event.preventDefault(); event.stopPropagation();
      if (unfold || fold) setExpanded(down);
    }
  }, {capture:true, passive:false});
  quickView = createQuickChatView(quick, qaStyles, { onAction, onClose:closeComposer,
    onBusy:busy => { composerBusy = busy; } });
  quickView.update(false);
  window.addEventListener('blur', () => { if (composing && !composerBusy) closeComposer(); });
  const badge = document.createElement('span');
  badge.className = 'minduck-notification-badge';
  badge.setAttribute('aria-hidden', 'true');
  badge.hidden = true;
  toggle.appendChild(badge);
  function setNotificationCount(value = 0) {
    const count = Number.isSafeInteger(value) ? Math.min(99999, Math.max(0, value)) : 0;
    if (count === notificationCount) return;
    notificationCount = count;
    badge.hidden = !count;
    badge.textContent = count > 99 ? '99+' : count ? String(count) : '';
    syncPresentation();
  }

  const handle = document.createElement('button');
  handle.type = 'button';
  handle.className = 'minduck-handle';
  handle.setAttribute('aria-label', '展开 Matter 快捷操作');
  handle.hidden = true;
  const expand = () => {
    actions.hidden = false;
    handle.hidden = true;
    actions.firstElementChild.focus({ preventScroll: true });
  };
  handle.addEventListener('focus', expand);
  handle.addEventListener('click', expand);
  document.body.append(stack, actions, handle);

  let taskActive = false, bodyBox = null, scale = 1;
  function setScale(value = 1) {
    if (value !== scale && motions.length) { stopMotion(); displayExpanded = expanded; }
    scale = Number.isFinite(value) ? clamp(value, .8, 1.5) : 1;
    for (const element of [stack, actions, handle]) element.style.setProperty('--minduck-panel-scale', scale);
  }
  function setOutput(text = '', detail = '', active) {
    setOutputs([{ text, detail, active: active ?? Boolean(String(text).trim() || String(detail).trim()) }]);
  }
  function setOutputs(tasks = []) {
    latestTasks = tasks;
    const seen = new Set();
    const available = tasks.filter(task => {
      const key = messageKey(task);
      const id = task.conversationId || 'current';
      if (!task.active || dismissed.has(key) || seen.has(id)) return false;
      seen.add(id); return true;
    });
    const byKey = new Map(available.map(task => [task.conversationId || 'current', task]));
    const previousOrder = queueKeys.join('\0');
    queueKeys = [...queueKeys.filter(key => byKey.has(key)),
      ...[...byKey.keys()].filter(key => !queueKeys.includes(key))];
    if (motions.length && previousOrder !== queueKeys.join('\0')) { stopMotion(); displayExpanded = expanded; }
    const queued = queueKeys.map(key => byKey.get(key));
    stack.dataset.messageCount = String(queued.length);
    stack.setAttribute('aria-label', `Matter 活动会话，${queued.length} 条消息待处理`);
    taskActive = queued.length > 0;
    if (!taskActive) { stopMotion(); expanded = displayExpanded = false; }
    const ids = new Set(queueKeys);
    for (const [id, output] of outputs) if (!ids.has(id)) {
      views.get(id)?.destroy(); views.delete(id);
      runningViews.get(id)?.destroy(); runningViews.delete(id); output.remove(); outputs.delete(id);
    }
    for (const task of queued) {
      const id = task.conversationId || 'current';
      const output = card(id);
      output.dataset.turnId = task.turnId || '';
      output.dataset.messageKey = messageKey(task);
      const message = output.querySelector('.minduck-message'), question = output.querySelector('.minduck-qa');
      message.disabled = !task.conversationId || typeof onAction !== 'function';
      output.setAttribute('aria-label', `打开会话：${task.detail || task.text || '当前任务'}`);
      const rows = [String(task.text || '').replace(/\s+/gu, ' ').trim(), String(task.detail || '').replace(/\s+/gu, ' ').trim()];
      if (!rows.some(Boolean)) rows[0] = '任务进行中';
      message.querySelectorAll('.minduck-output-line').forEach((line, index) => { line.textContent = rows[index]; });
      message.title = rows.filter(Boolean).join('\n');
      const running = output.querySelector('.minduck-running');
      const isRunning = task.status === 'running' && !task.qa;
      message.hidden = !!task.qa || isRunning;
      running.hidden = !isRunning;
      question.hidden = !task.qa;
      output.classList.toggle('has-qa', !!task.qa);
      if (task.qa) {
        if (!views.has(id)) views.set(id, createQaView(question, qaStyles, { onAction, onFocus }));
        views.get(id).update(task);
      }
      if (isRunning) {
        if (!runningViews.has(id)) runningViews.set(id, createRunningView(running, qaStyles, { onAction, onFocus, onReleaseFocus }));
        runningViews.get(id).update(task);
      } else runningViews.get(id)?.update(null);
      output.hidden = false;
    }
    // Retain an empty hidden status node for accessibility and legacy preview callers.
    if (!taskActive) { card('current').hidden = true; stack.hidden = true; }
    syncPresentation();
  }

  function overStack(point) {
    if (!point || stack.hidden) return false;
    const rect = stack.getBoundingClientRect();
    return point.x >= rect.left && point.x <= rect.right && point.y >= rect.top && point.y <= rect.bottom;
  }

  function overActions(point) {
    if (!point || actions.hidden || !bodyBox) return false;
    const rect = actions.getBoundingClientRect();
    const notes = composing && quick.shadowRoot.querySelector('.pet-quick-notes');
    if (notes) {
      const r = notes.getBoundingClientRect();
      if (point.x >= r.left && point.x <= r.right && point.y >= r.top && point.y <= r.bottom) return true;
    }
    // Once revealed, the figure's full extent and both buttons form one continuous hover area.
    // The same area owns native mouse input, including transparent corners and the connecting gap.
    return point.x >= Math.min(bodyBox.x, rect.left) - 12 * scale
      && point.x <= Math.max(bodyBox.x + bodyBox.w, rect.right) + 12 * scale
      && point.y >= Math.min(bodyBox.y, rect.top) - 12 * scale
      && point.y <= Math.max(bodyBox.y + bodyBox.h, rect.bottom) + 12 * scale;
  }

  function overHandle(point) {
    if (!point || handle.hidden) return false;
    const rect = handle.getBoundingClientRect();
    return point.x >= rect.left && point.x <= rect.right && point.y >= rect.top && point.y <= rect.bottom;
  }

  function position(element, center, top) {
    // offsetWidth/Height round fractional CSS pixels and can push scaled panels past an edge.
    const style = getComputedStyle(element);
    const width = parseFloat(style.width) * scale, height = parseFloat(style.height) * scale;
    const left = clamp(center - width / 2, 16, Math.max(16, innerWidth - width - 16));
    const y = clamp(top, 16, Math.max(16, innerHeight - height - 16));
    element.style.transform = `translate3d(${left.toFixed(2)}px, ${y.toFixed(2)}px, 0) scale(${scale})`;
  }

  function layout(body, { conversationOpen = false, pointer = null, hoveringBody = false } = {}) {
    lastLayout = [body, {conversationOpen, pointer, hoveringBody}];
    const box = body?.box;
    bodyBox = box ?? null;
    const manipulating = body?.pressing || ['drag', 'air', 'land'].includes(body?.mode);
    if (motions.length && (!box || manipulating || conversationOpen || motionBounds !== `${innerWidth}:${innerHeight}:${scale}`)) {
      stopMotion(); displayExpanded = expanded;
    }
    stack.hidden = !box || !taskActive || conversationOpen;
    syncPresentation();
    const hovered = box && (composing || hoveringBody || overActions(pointer) || overHandle(pointer)
      || actions.querySelector(':focus-visible'));
    actions.hidden = !box || manipulating || !hovered;
    handle.hidden = !box || manipulating || !actions.hidden;
    if (!box) return;
    const center = box.x + box.w / 2;
    // Reserve the expanded controls even while only their handle is showing.
    const controlsTop = clamp(box.y + box.h + 6 * scale, 16, Math.max(16, innerHeight - 42 * scale - 16));
    if (!stack.hidden) {
      const visible = [...outputs.values()].filter(output => !output.hidden);
      const output = visible[0];
      const offset = Number.parseFloat(stack.style.getPropertyValue('--stack-offset')) || 0;
      // Size the viewport to at most three complete rows, including mixed-height QA cards.
      const heights = visible.map(card => card.firstElementChild.scrollHeight).sort((a, b) => a - b).slice(0, 3);
      const contentHeight = displayExpanded ? heights.reduce((sum, height) => sum + height, 0) + (heights.length - 1) * 8 + 16
        : output.firstElementChild.scrollHeight + offset;
      const needed = contentHeight * scale;
      const aboveEnd = Math.min(box.y, body.bubble.y) - 16 * scale;
      const belowStart = controlsTop + (42 + 16) * scale;
      const roomAbove = aboveEnd - 16, roomBelow = innerHeight - 16 - belowStart;
      const below = needed > roomAbove && roomBelow > roomAbove;
      const room = below ? roomBelow : roomAbove;
      // Compact messages keep their padding even on a crowded display. Long questions can scroll.
      const limit = (displayExpanded || output.classList.contains('has-qa')) && room > 0 ? room : Math.max(room, needed);
      const maxHeight = Math.max(0, Math.min(innerHeight - 32, limit)) / scale;
      stack.style.maxHeight = `${maxHeight}px`;
      list.style.maxHeight = `${Math.max(0, displayExpanded ? Math.min(maxHeight, contentHeight) : maxHeight - offset)}px`;
      for (const card of visible) card.style.maxHeight = `${Math.max(0, maxHeight - (displayExpanded ? 16 : offset))}px`;
      position(stack, center, below ? belowStart : aboveEnd - parseFloat(getComputedStyle(stack).height) * scale);
    }
    updateScrollEdges();
    // Artwork bounds include props; anchor the controls to the body's standing position.
    if (!actions.hidden) position(actions, body.x, controlsTop);
    if (!handle.hidden) position(handle, body.x, controlsTop);
  }

  setOutput();
  return {
    surfaces: [stack, actions, handle],
    // The 6px handle and 42px capsule share their top edge, 6px below the body.
    get floorGap() { return 64 * scale; },
    setScale,
    setOutput,
    setOutputs,
    setNotificationCount,
    hit: (point) => overActions(point) || overHandle(point) || overStack(point),
    layout,
  };
}
